#!/usr/bin/env bash
# SessionStart directive — residual-risk sign-off facet of the security-threat-model role.
. "${CLAUDE_PLUGIN_ROOT_CORE:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../../core" && pwd -P)}/hooks/lib/role-directive.sh"
core_role_directive $'YOU DECIDE: residual-risk sign-off discipline — every residual-risk-note must carry a post-mitigation rating and an explicit approver reference' $'USE WHEN: writing or reviewing a residual-risk-note in a security-threat-model proposal or record' $'PRODUCES: a residual-risk-note carrying (1) a post-mitigation rating (the residual risk level after mitigations are applied — not a restatement of the pre-mitigation rating), and (2) an explicit approver reference: a citation to docs/specs/approvers.md (contract v3 \xc2\xa719 Approve gate), or the literal word "Approve"/"approver" tied to a named account' $'HAND-OFF: this does not invent a second sign-off mechanism — it makes the existing docs/specs/approvers.md Approve gate mechanically checkable inside the residual-risk-note itself.\nA residual-risk-note with a rating but no approver reference is incomplete and will be refused by methodology-gate.sh on write.'
